G=[[9]*24 for _ in range(30)]
# Target bands
for r in range(14,19): G[r]=[1]+[5]*22+[1]
for r in range(20,24): G[r]=[5]+[3]*22+[5]
for r in range(25,29): G[r]=[8]+[1]*22+[8]
# 3/1 motif at rows 7-9, cols 3-11 -> target bands with fill 3 and fill 1
# For fill 3: source 3 maps to border 5; source 1 maps to fill 3.
# For fill 1: source 1 maps to border 8; source 3 maps to fill 1.
sourceB=[[9,3,3,3,3,3,3,3,3],[3,3,1,1,1,1,1,3,3],[9,3,3,3,3,3,3,3,9]]
for r0,fill,border in [(21,3,5),(26,1,8)]:
 for dr,row in enumerate(sourceB):
  for dc,v in enumerate(row):
   if v==fill: G[r0+dr][3+dc]=border
# 5/3 motif rows 2-4 cols17-21 -> target bands with fill 5 and fill 3
sourceC=[[5]*5,[5,3,3,3,5],[5]*5]
for r0,fill,border in [(16,5,1),(21,3,5)]:
 for dr,row in enumerate(sourceC):
  for dc,v in enumerate(row):
   if v==fill: G[r0+dr][17+dc]=border
# 1 square -> panel fill 1 is translated to border 8
for r in (27,28):
 for c in (13,14): G[r][c]=8
print('\n'.join(' '.join(map(str,row)) for row in G))

